package assess

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func TestAssessHotspots(t *testing.T) {
	dir := t.TempDir()
	files := map[string]string{
		"a/a.go":      "package a\n\nimport (\n\t\"fmt\"\n\t\"os\"\n)\n\nfunc Big(x, y int) {\n\tfmt.Println(x)\n\t_ = os.Args\n\t_ = y\n}\n",
		"a/a_test.go": "package a\n",
		"b/b.go":      "package b\n\nimport \"strings\"\n\nfunc Small() { _ = strings.Join }\n",
		"b/gen.go":    "// Code generated by x. DO NOT EDIT.\n\npackage b\n\nfunc Huge() {\n\n\n\n\n\n\n\n\n\n\n\n}\n",
		"c/c.go":      "package c\n\nfunc {\n",
		"d/skip.go":   "package d\n\nfunc Untracked() {}\n",
	}
	for name, body := range files {
		p := filepath.Join(dir, name)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	for _, args := range [][]string{{"init", "-q"}, {"add", "a", "b", "c"}} {
		cmd := exec.Command("git", args...)
		cmd.Dir = dir
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, out)
		}
	}

	rep, err := AssessHotspots(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(rep.Files) != 3 || rep.Files[0].Path != "a/a.go" || rep.Files[0].Lines != 12 {
		t.Fatalf("files = %+v (generated and untracked files must be excluded, largest first)", rep.Files)
	}
	if len(rep.Funcs) != 2 || rep.Funcs[0].Name != "Big" || rep.Funcs[0].Lines != 5 || rep.Funcs[0].Params != 2 {
		t.Fatalf("funcs = %+v", rep.Funcs)
	}
	if len(rep.Packages) != 2 || rep.Packages[0].Dir != "a" || rep.Packages[0].Imports != 2 || rep.Packages[0].TestFiles != 1 {
		t.Fatalf("packages = %+v", rep.Packages)
	}
	if len(rep.Untested) != 1 || rep.Untested[0].Dir != "b" {
		t.Fatalf("untested = %+v", rep.Untested)
	}
	if len(rep.ParseFails) != 1 || rep.ParseFails[0] != "c/c.go" {
		t.Fatalf("parse fails = %v", rep.ParseFails)
	}

	text := RenderHotspotsText(rep)
	for _, want := range []string{"Largest Go files", "a/a.go:8 Big (2 params)", "Packages without tests (1)", "Unparsable files (1): c/c.go"} {
		if !strings.Contains(text, want) {
			t.Errorf("text missing %q:\n%s", want, text)
		}
	}
}
